// Проверка подписи RAHTIS на входящем вопросе.
//
// Платформа подписывает исходящий запрос тем же секретом, которым мы
// подписываем обратные: HMAC-SHA256 на AGENT_WEBHOOK_SECRET от строки
// `${timestamp}.${body}`, заголовок x-rahtis-signature вида sha256=<hex>.
//
// Без проверки вебхук открыт: кто узнал адрес, тот пришлёт свой
// conversation_id и получит ответ агента в чужой тред.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.AGENT_WEBHOOK_SECRET) SECRET = $vars.AGENT_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('AGENT_WEBHOOK_SECRET не задан: создайте переменную в n8n или впишите значение в SECRET.');
const secret = SECRET;

// Сырое тело подписи. n8n отдаёт его по-разному: строкой, буфером,
// разобранным объектом, а при rawBody иногда двоичным вложением. Подпись
// считается от БАЙТОВ, которые прислала платформа, поэтому читаем все
// формы, а разбор JSON оставляем на потом.
function rawBody() {
  try {
    const bin = $input.item.binary;
    if (bin && bin.data && bin.data.data) return Buffer.from(bin.data.data, 'base64').toString('utf8');
  } catch (e) {}
  const b = $json.body;
  if (typeof b === 'string') return b;
  if (Buffer.isBuffer(b)) return b.toString('utf8');
  if (b && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data).toString('utf8');
  return JSON.stringify(b || {});
}
const raw = rawBody();
const ts = $json.headers['x-rahtis-timestamp'] || '';
const given = $json.headers['x-rahtis-signature'] || '';

// Окно 300 секунд: перехваченный запрос нельзя повторить назавтра.
const age = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
const fresh = Number.isFinite(age) && age <= 300;

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(given);
const signed = a.length === b.length && crypto.timingSafeEqual(a, b);

let p = {};
try { p = JSON.parse(raw); } catch (e) { try { p = (typeof $json.body === 'object' && $json.body) || {}; } catch (e2) { p = {}; } }

return [{
  json: {
    ok: signed && fresh,
    why: signed ? (fresh ? null : 'stale') : 'signature',
    conversation_id: p.conversation_id,
    dispatch_token: p.dispatch_token,
    audience: p.audience,
    party_role: p.party_role,
    company_name: p.company_name,
    text: p.text || '',
  },
}];

// Первый запрос к Claude: вопрос плюс наставление и инструменты.
//
// Ни того ни другого этот узел больше не собирает — их присылает
// платформа в теле запроса. Так правда о ролях лежит в одном месте и
// едет вместе с кодом.
//
// Раньше наставление жило здесь, и это стоило дорого: аудиторию
// оператора завели в базе и в файле воркфлоу, а в работающем n8n
// осталась прежняя ветка — помощник ответил оператору «платформа
// открывает мне только данные вашей компании», то есть отказал ровно в
// том, ради чего его и звали. Файл был прав, работа шла по старому.
//
// Компания по-прежнему НЕ передаётся в инструментах: она выводится из
// треда по dispatch_token внутри базы, и поля, куда вписать чужую, не
// существует. Это свойство контракта, а не проверка.
//
// state нужен циклу инструментов: «Разобрать ответ» берёт его отсюда на
// первом круге, дальше — у «Добавить результат».
//
// disable_parallel_tool_use: /api/agent/tools принимает один инструмент
// за вызов. Разрешив параллельные, мы потеряли бы второй.

const src = $json;

if (!src.system || !Array.isArray(src.tools)) {
  throw new Error('Platforma ne prislala system i tools: obnovite prilozhenie.');
}

const state = {
  system: src.system,
  tools: src.tools,
  iterations: 0,
  messages: [{ role: 'user', content: String(src.text || '') }],
};

return [{ json: { state, payload: JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 2048,
  output_config: { effort: 'medium' },
  system: state.system,
  tools: state.tools,
  tool_choice: { type: 'auto', disable_parallel_tool_use: true },
  messages: state.messages,
}) } }];

// Разбор ответа модели.
//
// Ответ ассистента кладётся в историю ЦЕЛИКОМ, вместе с блоками tool_use:
// следующий запрос обязан содержать тот же tool_use, к которому мы вернём
// tool_result, иначе API не свяжет их.

// Состояние разговора берётся у предыдущего узла, а не из ответа HTTP:
// узел HTTP заменяет элемент целиком, и всё, что мы к нему прикрепили,
// до сюда не доезжает. На первом круге состояние даёт сборщик запроса,
// на следующих — последний прогон «Добавить результат».
let prev = null;
try {
  const added = $('Добавить результат').all();
  if (added.length) prev = added[added.length - 1].json.__state;
} catch (e) {
  prev = null;
}
if (!prev) prev = $('Собрать первый запрос').first().json.state;

const res = $json;

if (res.error || !Array.isArray(res.content)) {
  const why = res.error ? (res.error.message || JSON.stringify(res.error)) : (res.message || 'ответ модели не разобран');
return [{ json: { __state: prev, done: true, failed: true, model_error: String(why).slice(0, 300),
  reply: 'Palvelu ei vastaa juuri nyt. / Служба сейчас не отвечает.' } }];
}

const messages = prev.messages.concat([{ role: 'assistant', content: res.content }]);
const next = Object.assign({}, prev, { messages });

const toolUse = res.content.find((b) => b.type === 'tool_use');
const text = res.content.filter((b) => b.type === 'text').map((b) => b.text).join('').trim();

// Потолок на круги: модель, зациклившаяся на инструментах, не должна
// молотить бесконечно. Четырёх хватает на «найди заказ, посмотри статус,
// подними пункт договора».
const overLimit = next.iterations >= 4;

if (res.stop_reason === 'tool_use' && toolUse && !overLimit) {
  return [{ json: { __state: next, done: false, tool: toolUse.name, tool_use_id: toolUse.id, args: toolUse.input || {} } }];
}

return [{ json: {
  __state: next,
  done: true,
  reply: text || 'En löytänyt vastausta. Ole yhteydessä operaattoriin. / Ответа не нашёл, напишите оператору.',
} }];

// Подпись вызова инструмента.
//
// conversation_id и dispatch_token — из треда, который открыла платформа.
// Пропуск живёт до ответа: скомпрометированный n8n получит инструменты
// только по треду, который сейчас в работе, а не по любому, чей
// идентификатор он когда-то видел.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.AGENT_WEBHOOK_SECRET) SECRET = $vars.AGENT_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('AGENT_WEBHOOK_SECRET не задан: создайте переменную в n8n или впишите значение в SECRET.');
const secret = SECRET;
const st = $json.__state;
// Тело для узла HTTP.
//
// Узел отправляет его в режиме JSON: сырой режим в этой установке
// n8n тела не передавал вовсе — платформа видела 0 байт при
// подписанных 544, и ошибки при этом не возникало. Режим JSON
// проверен на запросе к модели, поэтому он же и здесь.
//
// Узел разбирает строку обратно в объект и собирает JSON заново, так
// что байты на проводе уже не те, от которых считалась подпись.
// Платформа поэтому сверяет подпись и с приведённым видом тела.
const payload = JSON.stringify({
  conversation_id: st.conversation_id,
  dispatch_token: st.dispatch_token,
  tool: $json.tool,
  args: $json.args,
});

const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + payload).digest('hex');

// Под обоими именами: выражение в узле уже дважды разъезжалось с полем.
return [{ json: { payload, body: payload, timestamp, signature, __state: st, tool_use_id: $json.tool_use_id } }];

// Результат инструмента обратно в разговор.
//
// Отказ тоже возвращается модели — блоком с is_error, а не молчанием:
// «заказа с таким номером нет» это ответ, который модель должна
// пересказать пользователю, а не повод оборвать разговор.

// last(), а не item(): узел отрабатывает по разу на каждый круг
// инструментов, и нужен самый свежий прогон.
const runs = $('Подпись: инструмент').all();
const signed = runs[runs.length - 1].json;
const st = signed.__state;
const res = $json;

const isError = Boolean(res.error);
const content = isError
  ? String(res.error) + (res.detail ? ': ' + res.detail : '')
  : JSON.stringify(res);

const messages = st.messages.concat([{
  role: 'user',
  content: [{
    type: 'tool_result',
    tool_use_id: signed.tool_use_id,
    content,
    is_error: isError,
  }],
}]);

const next = Object.assign({}, st, { messages, iterations: st.iterations + 1 });

return [{ json: { __state: next, payload: JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 2048,
  output_config: { effort: 'medium' },
  system: next.system,
  tools: next.tools,
  tool_choice: { type: 'auto', disable_parallel_tool_use: true },
  messages: next.messages,
}) } }];

// Подпись ответа в тред.
//
// Токен гасится на стороне платформы: повторить тот же ответ вторым
// запросом нельзя.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.AGENT_WEBHOOK_SECRET) SECRET = $vars.AGENT_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('AGENT_WEBHOOK_SECRET не задан: создайте переменную в n8n или впишите значение в SECRET.');
const secret = SECRET;
const st = $json.__state;
// Тело для узла HTTP.
//
// Узел отправляет его в режиме JSON: сырой режим в этой установке
// n8n тела не передавал вовсе — платформа видела 0 байт при
// подписанных 544, и ошибки при этом не возникало. Режим JSON
// проверен на запросе к модели, поэтому он же и здесь.
//
// Узел разбирает строку обратно в объект и собирает JSON заново, так
// что байты на проводе уже не те, от которых считалась подпись.
// Платформа поэтому сверяет подпись и с приведённым видом тела.
const payload = JSON.stringify({
  conversation_id: st.conversation_id,
  dispatch_token: st.dispatch_token,
  text: String($json.reply).slice(0, 8000),
});

const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + payload).digest('hex');

// Под обоими именами: выражение в узле уже дважды разъезжалось с полем.
return [{ json: { payload, body: payload, timestamp, signature, reply: $json.reply } }];

// Итог прогона. Платформа получает не только «да/нет», но и шаг, на
// котором всё встало: без этого отладка сводится к угадыванию.
const signed = $('Подпись: ответ').all();
const last = signed[signed.length - 1].json;
const parsed = $('Разобрать ответ').all();
const modelError = parsed.length ? parsed[parsed.length - 1].json.model_error : null;
// Что именно подписали и что на это сказал сервер. Обе стороны считают
// подпись от одной строки; расхождение видно только если сравнить их
// длины и метки времени, а по одному слову «mismatch» не разобрать.
const replyError = $json.error
  ? ('подписал ' + last.payload.length + ' Б, метка ' + last.timestamp + '; сервер: ' + JSON.stringify($json).slice(0, 300))
  : null;
/*
 * Отказы инструментов уезжают наружу вместе с итогом. Модель
 * пересказывает их своими словами — «сервис данных отвечает ошибкой», —
 * и по такому пересказу не понять ни кода, ни причины.
 */
const calls = (() => { try { return $('Вызвать инструмент').all(); } catch (e) { return []; } })();
const toolErrors = calls
  .map((c) => (c.json && c.json.error ? JSON.stringify(c.json).slice(0, 200) : null))
  .filter(Boolean);

return [{ json: {
  ok: !replyError && !modelError,
  stage: replyError ? 'reply' : (modelError ? 'model' : null),
  detail: replyError || modelError || null,
  reply: last.reply,
  tools: toolErrors,
} }];

// Отказ на входе. Причину возвращаем платформе: 'signature' — секреты
// разошлись, 'stale' — часы n8n убежали дальше окна в 300 секунд.
return [{ json: { ok: false, stage: 'signature', detail: $json.why || 'signature', tools: [] } }];
